+    /// Format a step display header (e.g., `[1/7] step_name — title`).
+    ///
+    /// The `index` is zero-based; implementations display it as one-based.
+    /// When `name` equals `title`, the separator and title are omitted.
+    fn format_step_header(&self, index: usize, total: usize, name: &str, title: &str) -> String {
+        if name == title {
+            format!("[{}/{}] {}", index + 1, total, name)
+        } else {
+            format!("[{}/{}] {} — {}", index + 1, total, name, title)
+        }
+    }
+
+    /// Format a status indicator with the appropriate icon.
+    ///
+    /// Returns a plain-text status string (e.g., `[skip] Skipped`).
+    /// Themed implementations may add color and unicode icons.
+    fn format_status(&self, kind: StatusKind, message: &str) -> String {
+        kind.format_plain(message)
+    }
+
+    /// Create a live output callback for streaming command output.
