+    /// Returns `None` when live streaming is not supported or not
+    /// appropriate for the current output mode. Implementations may
+    /// use the spinner's progress bar for real-time updates.
+    fn create_output_callback(
+        &self,
+        _spinner: &dyn SpinnerHandle,
+        _base_message: String,
